int reallocate_array(void **ptr, size_t nmemb, size_t size) {
    if (!ptr) {
        return AVERROR(ENOMEM);
    }

    // Check for overflow in multiplication
    if (nmemb > SIZE_MAX / size) {
        return AVERROR(ENOMEM);
    }

    void *new_ptr = realloc(*ptr, nmemb * size);
    if (!new_ptr) {
        return AVERROR(ENOMEM);
    }

    *ptr = new_ptr;
    return 0;
}
